import{a6 as r,aq as s,an as n,ay as t,cU as i,ax as d,aw as l,b_ as o,bJ as u}from"./index-dP4jQgVM.js";const b={},c={class:"lesson-page"},g={class:"shell"},h={class:"pager","aria-label":"Tutorialnavigation"};function m(v,e){const a=o("RouterLink");return u(),s("main",c,[n("div",g,[t(a,{to:"/medientechnik/figma",class:"back"},{default:i(()=>[...e[0]||(e[0]=[d("← Figma",-1)])]),_:1}),e[4]||(e[4]=l('<header data-v-ab653729><p class="eyebrow" data-v-ab653729>FIGMA FÜR ANFÄNGER · SCHRITT 1 VON 16</p><h1 data-v-ab653729>Figma kennenlernen und anmelden</h1><p class="goal" data-v-ab653729>Du erklärst den Unterschied zwischen Figma und InDesign und meldest dich mit deiner Schul-E-Mail-Adresse bei Figma an.</p></header><p class="intro" data-v-ab653729>Figma ist ein Gestaltungsprogramm, mit dem du vor allem digitale Oberflächen wie Websites und Apps entwerfen kannst. Du kannst mehrere Bildschirmansichten miteinander verbinden und als klickbaren Prototyp ausprobieren. Mehrere Personen können gemeinsam an einer Datei arbeiten.</p><section aria-labelledby="school-license-title" data-v-ab653729><h2 id="school-license-title" data-v-ab653729>Schullizenz und Zusammenarbeit</h2><p data-v-ab653729>Mit deiner Schul-E-Mail-Adresse erhältst du Zugang zur <strong data-v-ab653729>Figma-Schullizenz</strong>. Diese bietet Funktionen einer <strong data-v-ab653729>Pro-Lizenz</strong>, mit denen ihr besonders gut zusammenarbeiten könnt: Ihr könnt gemeinsam an Dateien gestalten und euch gegenseitig Rückmeldung geben.</p><p data-v-ab653729>Die <strong data-v-ab653729>KI-Funktionen stehen in der Schullizenz nicht zur Verfügung</strong>. Melde dich deshalb unbedingt mit deiner Schul-E-Mail-Adresse an, um den Zugang der Schule zu nutzen.</p></section><section aria-labelledby="comparison-title" data-v-ab653729><h2 id="comparison-title" data-v-ab653729>Figma und InDesign im Vergleich</h2><dl data-v-ab653729><div data-v-ab653729><dt data-v-ab653729>Figma</dt><dd data-v-ab653729>Du gestaltest vor allem für den Bildschirm, zum Beispiel eine Website oder App. Ein Prototyp zeigt, wie sich die Oberfläche beim Klicken verhält.</dd></div><div data-v-ab653729><dt data-v-ab653729>InDesign</dt><dd data-v-ab653729>Du gestaltest vor allem Seitenlayouts, zum Beispiel Flyer, Plakate und mehrseitige Broschüren, und bereitest sie für Druck oder digitale Ausgabe vor.</dd></div></dl><p data-v-ab653729>Beide Programme arbeiten mit Texten, Bildern, Formen und Farben. Ihr Schwerpunkt und die Art der Ausgabe unterscheiden sich.</p></section><section aria-labelledby="terms-title" data-v-ab653729><h2 id="terms-title" data-v-ab653729>Einfach erklärt</h2><dl data-v-ab653729><div data-v-ab653729><dt data-v-ab653729>Prototyp</dt><dd data-v-ab653729>Eine ausprobierbare Vorschau, in der du zum Beispiel zwischen gestalteten Ansichten wechseln kannst.</dd></div><div data-v-ab653729><dt data-v-ab653729>Schul-E-Mail-Adresse</dt><dd data-v-ab653729>Deine persönliche E-Mail-Adresse der Schule. Verwende sie für dieses Tutorial bei der Anmeldung in Figma.</dd></div></dl></section><section class="practice" aria-labelledby="practice-title" data-v-ab653729><h2 id="practice-title" data-v-ab653729>So gehst du vor</h2><ol data-v-ab653729><li data-v-ab653729><strong data-v-ab653729>Figma öffnen:</strong> Rufe <a href="https://www.figma.com/" target="_blank" rel="noopener noreferrer" data-v-ab653729>figma.com</a> im Browser auf oder öffne die Desktop-App.</li><li data-v-ab653729><strong data-v-ab653729>Schul-E-Mail-Adresse verwenden:</strong> Wähle die Anmeldung. Verwende für das Tutorial unbedingt deine <strong data-v-ab653729>persönliche Schul-E-Mail-Adresse</strong>, keine private Adresse.</li><li data-v-ab653729><strong data-v-ab653729>Vorhandenes Schulkonto:</strong> Wenn du bereits ein Figma-Konto mit deiner Schul-E-Mail-Adresse hast, melde dich damit an. Nutze gegebenenfalls die von der Schule vorgegebene Anmeldemethode.</li><li data-v-ab653729><strong data-v-ab653729>Neues Konto:</strong> Falls du noch kein Konto mit der Schul-E-Mail-Adresse hast, wähle die Registrierung und folge den angezeigten Schritten. Bestätige deine Adresse, falls Figma dich dazu auffordert. Frage deine Lehrkraft, wenn du bei der Anmeldung oder beim Zugriff auf deine Schul-E-Mails Hilfe brauchst.</li><li data-v-ab653729><strong data-v-ab653729>Anmeldung prüfen:</strong> Kontrolliere in deinen Kontoeinstellungen, ob deine Schul-E-Mail-Adresse zum angemeldeten Konto gehört. Melde dich bei Bedarf ab und mit dem Schulkonto erneut an.</li><li data-v-ab653729><strong data-v-ab653729>Schullizenz verifizieren:</strong> Du wirst nun aufgefordert, deine Schullizenz zu verifizieren. Folge den angezeigten Schritten und verwende dabei deine Schul-E-Mail-Adresse. Falls du Unterstützung benötigst, frage deine Lehrkraft.</li></ol></section><section class="check" aria-labelledby="check-title" data-v-ab653729><h2 id="check-title" data-v-ab653729>Prüfe dein Ergebnis</h2><p data-v-ab653729>Du bist mit deiner Schul-E-Mail-Adresse angemeldet und kannst erklären, wofür du Figma und InDesign jeweils einsetzen würdest.</p></section>',7)),n("nav",h,[t(a,{to:"/medientechnik/figma/lerninhalte"},{default:i(()=>[...e[1]||(e[1]=[d("← Übersicht Lerninhalte",-1)])]),_:1}),e[3]||(e[3]=n("span",null,"1 / 16",-1)),t(a,{to:"/medientechnik/figma/tutorial/2"},{default:i(()=>[...e[2]||(e[2]=[d("Weiter zu Schritt 2 →",-1)])]),_:1})])])])}const f=r(b,[["render",m],["__scopeId","data-v-ab653729"]]);export{f as default};
